 56→}
 57→
 58→// toolResultFileJSON carries structured file metadata from Read/Edit tool results.
 59→type toolResultFileJSON struct {
 60→	FilePath string `json:"filePath"`
 61→	NumLines int    `json:"numLines,omitempty"`
 62→}
 63→
 64→// userTextBlock is a text block within user message content.
 65→type userTextBlock struct {
 66→	ID   string `json:"id,omitempty"`
 67→	Text string `json:"text"`
 68→}
 69→
 70→// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
 71→//
 72→// The output format puts version, agent, and cli_version on every line,
 73→// merges streaming assistant fragments with the same message ID, and inlines
 74→// tool results into the preceding assistant's tool_use blocks:
 75→//
 76→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
 77→//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
 78→func Compact(content []byte, opts MetadataFields) ([]byte, error) {
 79→	// Formats that need detection on raw content before line truncation:
 80→	// - Single-object formats (OpenCode, Gemini): SliceFromLine would cut
 81→	//   a JSON object mid-value. They handle StartLine as a message-index offset.
 82→	// - Codex: session_meta header is only on the first line. Codex handles
 83→	//   StartLine as a response_item index offset.
 84→	if isOpenCodeFormat(content) {
 85→		return compactOpenCode(content, opts)
 86→	}
 87→
 88→	if isGeminiFormat(content) {
 89→		return compactGemini(content, opts)
 90→	}
 91→
 92→	if isCodexFormat(content) {
 93→		return compactCodex(content, opts)
 94→	}
 95→
 96→	truncated := transcript.SliceFromLine(content, opts.StartLine)
 97→	if truncated == nil {
 98→		truncated = []byte{}
 99→	}
100→
101→	if isDroidFormat(truncated) {
102→		return compactDroid(truncated, opts)
103→	}
104→
105→	return compactJSONL(truncated, opts)
106→}
107→
108→// droppedTypes are JSONL entry types that carry no parser-relevant data.
109→var droppedTypes = map[string]bool{
110→	"progress":              true,
111→	"file-history-snapshot": true,
112→	"queue-operation":       true,
113→	"system":                true,
114→}
115→
116→// userAliases maps JSONL type/role values to the canonical "user" kind.
117→// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
118→var userAliases = map[string]bool{
119→	transcript.TypeUser: true,
120→	"human":             true,
121→}
122→
123→// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
124→// JSONL transcript line. It checks the "type" field, then falls back to "role".
125→// Returns "" for unrecognised or dropped entries.
126→func normalizeKind(raw map[string]json.RawMessage) string {
127→	kind := unquote(raw["type"])
128→	if kind == "" {
129→		kind = unquote(raw["role"])
130→	}
131→
132→	if droppedTypes[kind] {
133→		return ""
134→	}
135→	if userAliases[kind] {
136→		return transcript.TypeUser
137→	}
138→	if kind == transcript.TypeAssistant {
139→		return transcript.TypeAssistant
140→	}
141→	return ""
142→}
143→
144→// linePreprocessor transforms a parsed JSONL line before conversion.
145→type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage
146→
147→// parsedEntry is an intermediate representation of a JSONL line used during
148→// the two-pass compact conversion.
149→type parsedEntry struct {
150→	kind         string // "user" or "assistant"
151→	ts           json.RawMessage
152→	id           string            // message ID (assistant only)
153→	userID       string            // prompt ID (user only, e.g. Claude's promptId)
154→	inputTokens  int               // API input tokens (assistant only)
155→	outputTokens int               // API output tokens (assistant only)
156→	content      json.RawMessage   // stripped assistant content array, or nil
157→	userText     string            // extracted user text
158→	userImages   []json.RawMessage // image blocks from user messages
159→	toolResults  []toolResultEntry // user tool_result entries
160→}
161→
162→// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
163→// transcript.jsonl format.
164→func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
165→	return compactJSONLWith(content, opts, nil)
166→}
167→
168→func compactJSONLWith(content []byte, opts MetadataFields, preprocess linePreprocessor) ([]byte, error) {
169→	base := newTranscriptLine(opts)
170→
171→	// Pass 1: parse all lines into intermediate entries.
172→	entries, err := parseJSONLEntries(content, preprocess)
173→	if err != nil {
174→		return nil, err
175→	}
176→
177→	// Pass 2: merge and emit.
178→	var result []byte
179→	for i := 0; i < len(entries); i++ {
180→		e := entries[i]
181→
182→		switch e.kind {
183→		case transcript.TypeAssistant:
184→			// Merge consecutive assistant entries with the same message ID.
185→			merged := e
186→			for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
187→				i++
188→				merged = mergeAssistantEntries(merged, entries[i])
189→			}
190→
191→			// Look ahead for user tool_result entries to inline.
192→			if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
193→				userEntry := entries[i+1]
194→				merged = inlineToolResults(merged, userEntry)
195→				i++ // consume the user tool_result entry
196→
197→				// If the consumed user entry also had text or image content, emit it
198→				// as a separate user line after the assistant.
199→				if userEntry.userText != "" || len(userEntry.userImages) > 0 {
200→					emitAssistant(&result, base, merged)
201→					emitUser(&result, base, userEntry)
202→					continue
203→				}
204→			}
205→
206→			if isEmptyContentArray(merged.content) {
207→				continue
208→			}
209→
210→			emitAssistant(&result, base, merged)
211→
212→		case transcript.TypeUser:
213→			// User entries that are purely tool results were already consumed
214→			// by the assistant look-ahead above. If we reach one here it was
215→			// not preceded by an assistant with a matching tool_use, so emit
216→			// it only if it has text or image content.
217→			if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
218→				continue
219→			}
220→			emitUser(&result, base, e)
221→		}
222→	}
223→
224→	return result, nil
225→}
226→
227→func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
228→	line := base
229→	line.Type = transcript.TypeAssistant
230→	line.TS = e.ts
231→	line.ID = e.id
232→	line.InputTokens = e.inputTokens
233→	line.OutputTokens = e.outputTokens
234→	line.Content = e.content
235→	appendLine(result, line)
236→}
237→
238→func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
239→	var blocks []json.RawMessage
240→
241→	// Text block (with optional prompt ID).
242→	if e.userText != "" || len(e.userImages) == 0 {
243→		b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
244→		if err != nil {
245→			return
246→		}
247→		blocks = append(blocks, b)
248→	}
249→
250→	// Image blocks passed through verbatim.
251→	blocks = append(blocks, e.userImages...)
252→
253→	contentJSON, err := json.Marshal(blocks)
254→	if err != nil {
255→		return
256→	}
257→
258→	line := base
259→	line.Type = transcript.TypeUser
260→	line.TS = e.ts
261→	line.Content = contentJSON
262→	appendLine(result, line)
263→}
264→
265→// appendLine marshals a transcriptLine and appends it (with newline) to result.
266→func appendLine(result *[]byte, line transcriptLine) {
267→	b, err := json.Marshal(line)
268→	if err != nil {
269→		return
270→	}
271→	*result = append(*result, b...)
272→	*result = append(*result, '\n')
273→}
274→
275→// parseJSONLEntries parses all JSONL lines into intermediate entries,
276→// filtering dropped types and malformed lines.
277→func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
278→	reader := bufio.NewReader(bytes.NewReader(content))
279→	var entries []parsedEntry
280→
281→	for {
282→		lineBytes, err := reader.ReadBytes('\n')
283→		if err != nil && err != io.EOF {
284→			return nil, fmt.Errorf("reading JSONL line: %w", err)
285→		}
286→
287→		if len(bytes.TrimSpace(lineBytes)) > 0 {
288→			if e, ok := parseLine(lineBytes, preprocess); ok {
289→				entries = append(entries, e)
290→			}
291→		}
292→
293→		if err == io.EOF {
294→			break
295→		}
296→	}
297→
298→	return entries, nil
299→}
300→
301→// parseLine converts a single JSONL line into a parsedEntry.
302→// Returns ok=false for dropped/malformed lines.
303→func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
304→	var raw map[string]json.RawMessage
305→	if err := json.Unmarshal(lineBytes, &raw); err != nil {
306→		return parsedEntry{}, false
307→	}
308→
309→	if preprocess != nil {
310→		raw = preprocess(raw)
311→	}
312→
313→	kind := normalizeKind(raw)
314→	if kind == "" {
315→		return parsedEntry{}, false
316→	}
317→
318→	e := parsedEntry{
319→		kind: kind,
320→		ts:   raw["timestamp"],
321→	}
322→
323→	msg := parseMessage(raw)
324→
325→	switch kind {
326→	case transcript.TypeAssistant:
327→		if msg != nil {
328→			e.id = unquote(msg["id"])
329→			if contentRaw, ok := msg["content"]; ok {
330→				e.content = stripAssistantContent(contentRaw)
331→			}
332→			e.inputTokens, e.outputTokens = extractUsageTokens(msg)
333→		}
334→
335→	case transcript.TypeUser:
336→		e.userID = unquote(raw["promptId"])
337→		if msg != nil {
338→			if contentRaw, ok := msg["content"]; ok {
339→				uc := extractUserContent(contentRaw)
340→				e.userText = uc.text
341→				e.userImages = uc.images
342→				e.toolResults = uc.toolResults
343→			}
344→		}
345→		// Enrich tool results with metadata from toolUseResult.
346→		if turRaw, ok := raw["toolUseResult"]; ok {
347→			var tur map[string]json.RawMessage
348→			if json.Unmarshal(turRaw, &tur) == nil {
349→				e.toolResults = enrichToolResults(e.toolResults, tur)
350→			}
351→		}
352→	}
353→
354→	return e, true
355→}
356→
357→// mergeAssistantEntries combines two assistant entries with the same message ID.
358→// Content arrays are concatenated; the later timestamp and token counts win
359→// (streaming fragments report cumulative usage, so the last fragment is final).
360→func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
361→	merged := a
362→	merged.ts = b.ts
363→	if b.inputTokens > 0 {
364→		merged.inputTokens = b.inputTokens
365→	}
366→	if b.outputTokens > 0 {
367→		merged.outputTokens = b.outputTokens
368→	}
369→
370→	var aBlocks, bBlocks []json.RawMessage
371→	_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
372→	_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
373→	all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
374→	if data, err := json.Marshal(all); err == nil {
375→		merged.content = data
376→	}
377→
378→	return merged
379→}
380→
381→// inlineToolResults adds "result" fields to matching tool_use blocks in the
382→// assistant entry's content, using outputs from user tool_result entries.
383→func inlineToolResults(assistant, user parsedEntry) parsedEntry {
384→	var blocks []map[string]json.RawMessage
385→	if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
386→		return assistant
387→	}
388→
389→	for _, tr := range user.toolResults {
390→		// Find the tool_use block matching this tool_use_id.
391→		idx := -1
392→		for i := len(blocks) - 1; i >= 0; i-- {
393→			if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
394→				if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
395→					idx = i
396→					break
397→				}
398→			}
399→		}
400→		// No matching tool_use block: do not attach a result to unrelated content.
401→		if idx == -1 {
402→			continue
403→		}
404→
405→		blocks[idx]["result"] = buildToolResult(tr)
406→	}
407→
408→	if data, err := json.Marshal(blocks); err == nil {
409→		assistant.content = data
410→	}
411→
412→	return assistant
413→}
414→
415→// buildToolResult constructs the compact result object for a tool_use block,
416→// including optional rich metadata (file, matchCount) when available.
417→func buildToolResult(tr toolResultEntry) json.RawMessage {
418→	r := toolResultJSON{
419→		Output:     tr.output,
420→		Status:     "success",
421→		MatchCount: tr.matchCount,
422→	}
423→	if tr.isError {
424→		r.Status = toolResultStatusError
425→	}
426→	if tr.file != nil {
427→		r.File = &toolResultFileJSON{
428→			FilePath: tr.file.filePath,
429→			NumLines: tr.file.numLines,
430→		}
431→	}
432→	b, err := json.Marshal(r)
433→	if err != nil {
434→		return nil
435→	}
436→	return b
437→}
438→
439→// extractUsageTokens extracts input_tokens and output_tokens from a Claude
440→// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
441→func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
442→	usageRaw, ok := msg["usage"]
443→	if !ok {
444→		return 0, 0
445→	}
446→	var usage struct {
447→		InputTokens  int `json:"input_tokens"`
448→		OutputTokens int `json:"output_tokens"`
449→	}
450→	if json.Unmarshal(usageRaw, &usage) != nil {
451→		return 0, 0
452→	}
453→	return usage.InputTokens, usage.OutputTokens
454→}
455→
456→// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
457→func isEmptyContentArray(raw json.RawMessage) bool {
458→	var arr []json.RawMessage
459→	return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
460→}
461→
462→func hasToolResults(e parsedEntry) bool {
463→	return len(e.toolResults) > 0
464→}
465→
466→type toolResultEntry struct {
467→	toolUseID string
468→	output    string
469→	isError   bool
470→	// Rich metadata extracted from toolUseResult (optional).
471→	file       *toolResultFile // Read/Edit: file path and line count
472→	matchCount int             // Grep: number of matching files
473→}
474→
475→// toolResultFile carries structured file metadata from Read/Edit tool results.
476→type toolResultFile struct {
477→	filePath string
478→	numLines int // 0 if not available (e.g. Edit results)
479→}
480→
481→// enrichToolResults extracts structured metadata from a toolUseResult envelope
482→// and attaches it to the corresponding tool result entries.
483→//
484→// Claude Code's toolUseResult has different shapes per tool:
485→//   - Bash:  {stdout, stderr, interrupted, ...}
486→//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
487→//   - Grep:  {numFiles, numLines, filenames, content, mode}
488→//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
489→func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
490→	// Bash-style: stdout provides the output text.
491→	if stdout := unquote(tur["stdout"]); stdout != "" {
492→		switch len(results) {
493→		case 0:
494→			// Keep compatibility with transcripts that only include toolUseResult.
495→			results = append(results, toolResultEntry{output: stdout})
496→		case 1:
497→			results[0].output = stdout
498→		}
499→	}
500→
501→	// Read-style: file object with filePath and numLines.
502→	if fileRaw, ok := tur["file"]; ok {
503→		var file struct {
504→			FilePath string `json:"filePath"`
505→			NumLines int    `json:"numLines"`
506→		}
507→		if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
508→			applyToSingleResult(results, func(tr *toolResultEntry) {
509→				tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
510→			})
511→		}
512→	}
513→
514→	// Edit-style: top-level filePath.
515→	if filePath := unquote(tur["filePath"]); filePath != "" {
516→		applyToSingleResult(results, func(tr *toolResultEntry) {
517→			// Edit results don't have numLines.
518→			tr.file = &toolResultFile{filePath: filePath}
519→		})
520→	}
521→
522→	// Grep-style: numFiles as match count.
523→	if numFilesRaw, ok := tur["numFiles"]; ok {
524→		var n int
525→		if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
526→			applyToSingleResult(results, func(tr *toolResultEntry) {
527→				tr.matchCount = n
528→			})
529→		}
530→	}
531→
532→	return results
533→}
534→
535→// applyToSingleResult applies fn to the first (and expected only) tool result.
536→// toolUseResult is a single-tool envelope, so this is only meaningful when
537→// there's exactly one result entry.
538→func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
539→	if len(results) == 1 {
540→		fn(&results[0])
541→	}
542→}
543→
544→// parseMessage extracts and parses the "message" field from a JSONL transcript
545→// line. All JSONL agents nest content inside a "message" object.
546→func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
547→	msgRaw, ok := raw["message"]
548→	if !ok {
549→		return nil
550→	}
551→	var msg map[string]json.RawMessage
552→	if json.Unmarshal(msgRaw, &msg) == nil {
553→		return msg
554→	}
555→	return nil
556→}
557→
558→// userContent holds the extracted parts of a user message content array.
559→type userContent struct {
560→	text        string
561→	images      []json.RawMessage
562→	toolResults []toolResultEntry
563→}
564→
565→// extractUserContent separates user message content into text, images, and tool_result entries.
566→// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
567→func extractUserContent(contentRaw json.RawMessage) userContent {
568→	var str string
569→	if json.Unmarshal(contentRaw, &str) == nil {
570→		return userContent{text: textutil.StripIDEContextTags(str)}
571→	}
572→
573→	var blocks []json.RawMessage
574→	if json.Unmarshal(contentRaw, &blocks) != nil {
575→		return userContent{}
576→	}
577→
578→	var uc userContent
579→
580→	for _, blockRaw := range blocks {
581→		var block map[string]json.RawMessage
582→		if json.Unmarshal(blockRaw, &block) != nil {
583→			continue
584→		}
585→		blockType := unquote(block["type"])
586→
587→		switch blockType {
588→		case "tool_result":
589→			var isErr bool
590→			if raw, ok := block["is_error"]; ok {
591→				_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
592→			}
593→			uc.toolResults = append(uc.toolResults, toolResultEntry{
594→				toolUseID: unquote(block["tool_use_id"]),
595→				output:    unquote(block["content"]),
596→				isError:   isErr,
597→			})
598→
599→		case "image":
600→			uc.images = append(uc.images, blockRaw)
601→
602→		case transcript.ContentTypeText:
603→			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
604→			if stripped != "" {
605→				uc.text += stripped + "\n\n"
606→			}
607→		}
608→	}
609→
610→	uc.text = strings.TrimSpace(uc.text)
611→	return uc
612→}
613→
614→func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
615→	var str string
616→	if json.Unmarshal(contentRaw, &str) == nil {
617→		return contentRaw
618→	}
619→
620→	var blocks []map[string]json.RawMessage
621→	if json.Unmarshal(contentRaw, &blocks) != nil {
622→		return contentRaw
623→	}
624→
625→	result := make([]map[string]json.RawMessage, 0, len(blocks))
626→	for _, block := range blocks {
627→		blockType := unquote(block["type"])
628→
629→		if blockType == "thinking" || blockType == "redacted_thinking" {
630→			continue
631→		}
632→
633→		if blockType == transcript.ContentTypeToolUse {
634→			stripped := make(map[string]json.RawMessage)
635→			copyField(stripped, block, "type")
636→			copyField(stripped, block, "id")
637→			copyField(stripped, block, "name")
638→			copyField(stripped, block, "input")
639→			result = append(result, stripped)
640→			continue
641→		}
642→
643→		result = append(result, block)
644→	}
645→
646→	b, err := json.Marshal(result)
647→	if err != nil {
648→		return contentRaw
649→	}
650→	return b
651→}
652→
653→// copyField copies a single key from src to dst if it exists.
654→func copyField(dst, src map[string]json.RawMessage, key string) {
655→	if v, ok := src[key]; ok {
656→		dst[key] = v
657→	}
658→}
659→
660→// unquote JSON-decodes a raw message as a string. Returns "" on failure.
661→func unquote(raw json.RawMessage) string {
662→	var s string
663→	if json.Unmarshal(raw, &s) == nil {
664→		return s
665→	}
666→	return ""
667→}
668→

file.content:
// Package compact converts full.jsonl transcripts into a normalized,
// compact transcript.jsonl format. Only shared formatting is contained here.
package compact

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/textutil"
	"github.com/entireio/cli/cmd/entire/cli/transcript"
)

// MetadataFields provides metadata fields written to every output line.
type MetadataFields struct {
	Agent      string // e.g. "claude-code"
	CLIVersion string // e.g. "0.42.0"
	StartLine  int    // checkpoint_transcript_start (0 = no truncation)
}

// transcriptLine is the uniform output format for every line in transcript.jsonl.
// Field order is guaranteed by encoding/json (struct declaration order).
type transcriptLine struct {
	V            int             `json:"v"`
	Agent        string          `json:"agent"`
	CLIVersion   string          `json:"cli_version"`
	Type         string          `json:"type"`
	TS           json.RawMessage `json:"ts,omitempty"`
	ID           string          `json:"id,omitempty"`
	InputTokens  int             `json:"input_tokens,omitempty"`
	OutputTokens int             `json:"output_tokens,omitempty"`
	Content      json.RawMessage `json:"content"`
}

// newTranscriptLine returns a transcriptLine pre-filled with the shared
// metadata fields that are identical on every output line.
func newTranscriptLine(opts MetadataFields) transcriptLine {
	return transcriptLine{
		V:          1,
		Agent:      opts.Agent,
		CLIVersion: opts.CLIVersion,
	}
}

const toolResultStatusError = "error"

// toolResultJSON is the compact result object inlined into tool_use blocks.
type toolResultJSON struct {
	Output     string              `json:"output"`
	Status     string              `json:"status"`
	File       *toolResultFileJSON `json:"file,omitempty"`
	MatchCount int                 `json:"matchCount,omitempty"`
}

// toolResultFileJSON carries structured file metadata from Read/Edit tool results.
type toolResultFileJSON struct {
	FilePath string `json:"filePath"`
	NumLines int    `json:"numLines,omitempty"`
}

// userTextBlock is a text block within user message content.
type userTextBlock struct {
	ID   string `json:"id,omitempty"`
	Text string `json:"text"`
}

// Compact converts a full.jsonl transcript into the condensed transcript.jsonl format.
//
// The output format puts version, agent, and cli_version on every line,
// merges streaming assistant fragments with the same message ID, and inlines
// tool results into the preceding assistant's tool_use blocks:
//
//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"user","ts":"...","content":"..."}
//	{"v":1,"agent":"claude-code","cli_version":"0.42.0","type":"assistant","ts":"...","id":"msg_xxx","content":[{"type":"text","text":"..."},{"type":"tool_use","id":"...","name":"...","input":{...},"result":{"output":"...","status":"..."}}]}
func Compact(content []byte, opts MetadataFields) ([]byte, error) {
	// Formats that need detection on raw content before line truncation:
	// - Single-object formats (OpenCode, Gemini): SliceFromLine would cut
	//   a JSON object mid-value. They handle StartLine as a message-index offset.
	// - Codex: session_meta header is only on the first line. Codex handles
	//   StartLine as a response_item index offset.
	if isOpenCodeFormat(content) {
		return compactOpenCode(content, opts)
	}

	if isGeminiFormat(content) {
		return compactGemini(content, opts)
	}

	if isCodexFormat(content) {
		return compactCodex(content, opts)
	}

	truncated := transcript.SliceFromLine(content, opts.StartLine)
	if truncated == nil {
		truncated = []byte{}
	}

	if isDroidFormat(truncated) {
		return compactDroid(truncated, opts)
	}

	return compactJSONL(truncated, opts)
}

// droppedTypes are JSONL entry types that carry no parser-relevant data.
var droppedTypes = map[string]bool{
	"progress":              true,
	"file-history-snapshot": true,
	"queue-operation":       true,
	"system":                true,
}

// userAliases maps JSONL type/role values to the canonical "user" kind.
// Covers Claude Code ("user", "human") and Cursor ("user" via "role" field).
var userAliases = map[string]bool{
	transcript.TypeUser: true,
	"human":             true,
}

// normalizeKind returns the canonical entry kind ("user" or "assistant") for a
// JSONL transcript line. It checks the "type" field, then falls back to "role".
// Returns "" for unrecognised or dropped entries.
func normalizeKind(raw map[string]json.RawMessage) string {
	kind := unquote(raw["type"])
	if kind == "" {
		kind = unquote(raw["role"])
	}

	if droppedTypes[kind] {
		return ""
	}
	if userAliases[kind] {
		return transcript.TypeUser
	}
	if kind == transcript.TypeAssistant {
		return transcript.TypeAssistant
	}
	return ""
}

// linePreprocessor transforms a parsed JSONL line before conversion.
type linePreprocessor func(map[string]json.RawMessage) map[string]json.RawMessage

// parsedEntry is an intermediate representation of a JSONL line used during
// the two-pass compact conversion.
type parsedEntry struct {
	kind         string // "user" or "assistant"
	ts           json.RawMessage
	id           string            // message ID (assistant only)
	userID       string            // prompt ID (user only, e.g. Claude's promptId)
	inputTokens  int               // API input tokens (assistant only)
	outputTokens int               // API output tokens (assistant only)
	content      json.RawMessage   // stripped assistant content array, or nil
	userText     string            // extracted user text
	userImages   []json.RawMessage // image blocks from user messages
	toolResults  []toolResultEntry // user tool_result entries
}

// compactJSONL converts JSONL transcripts (Claude Code, Cursor) into the
// transcript.jsonl format.
func compactJSONL(content []byte, opts MetadataFields) ([]byte, error) {
	return compactJSONLWith(content, opts, nil)
}

func compactJSONLWith(content []byte, opts MetadataFields, preprocess linePreprocessor) ([]byte, error) {
	base := newTranscriptLine(opts)

	// Pass 1: parse all lines into intermediate entries.
	entries, err := parseJSONLEntries(content, preprocess)
	if err != nil {
		return nil, err
	}

	// Pass 2: merge and emit.
	var result []byte
	for i := 0; i < len(entries); i++ {
		e := entries[i]

		switch e.kind {
		case transcript.TypeAssistant:
			// Merge consecutive assistant entries with the same message ID.
			merged := e
			for i+1 < len(entries) && entries[i+1].kind == transcript.TypeAssistant && entries[i+1].id == e.id {
				i++
				merged = mergeAssistantEntries(merged, entries[i])
			}

			// Look ahead for user tool_result entries to inline.
			if i+1 < len(entries) && entries[i+1].kind == transcript.TypeUser && hasToolResults(entries[i+1]) {
				userEntry := entries[i+1]
				merged = inlineToolResults(merged, userEntry)
				i++ // consume the user tool_result entry

				// If the consumed user entry also had text or image content, emit it
				// as a separate user line after the assistant.
				if userEntry.userText != "" || len(userEntry.userImages) > 0 {
					emitAssistant(&result, base, merged)
					emitUser(&result, base, userEntry)
					continue
				}
			}

			if isEmptyContentArray(merged.content) {
				continue
			}

			emitAssistant(&result, base, merged)

		case transcript.TypeUser:
			// User entries that are purely tool results were already consumed
			// by the assistant look-ahead above. If we reach one here it was
			// not preceded by an assistant with a matching tool_use, so emit
			// it only if it has text or image content.
			if hasToolResults(e) && e.userText == "" && len(e.userImages) == 0 {
				continue
			}
			emitUser(&result, base, e)
		}
	}

	return result, nil
}

func emitAssistant(result *[]byte, base transcriptLine, e parsedEntry) {
	line := base
	line.Type = transcript.TypeAssistant
	line.TS = e.ts
	line.ID = e.id
	line.InputTokens = e.inputTokens
	line.OutputTokens = e.outputTokens
	line.Content = e.content
	appendLine(result, line)
}

func emitUser(result *[]byte, base transcriptLine, e parsedEntry) {
	var blocks []json.RawMessage

	// Text block (with optional prompt ID).
	if e.userText != "" || len(e.userImages) == 0 {
		b, err := json.Marshal(userTextBlock{ID: e.userID, Text: e.userText})
		if err != nil {
			return
		}
		blocks = append(blocks, b)
	}

	// Image blocks passed through verbatim.
	blocks = append(blocks, e.userImages...)

	contentJSON, err := json.Marshal(blocks)
	if err != nil {
		return
	}

	line := base
	line.Type = transcript.TypeUser
	line.TS = e.ts
	line.Content = contentJSON
	appendLine(result, line)
}

// appendLine marshals a transcriptLine and appends it (with newline) to result.
func appendLine(result *[]byte, line transcriptLine) {
	b, err := json.Marshal(line)
	if err != nil {
		return
	}
	*result = append(*result, b...)
	*result = append(*result, '\n')
}

// parseJSONLEntries parses all JSONL lines into intermediate entries,
// filtering dropped types and malformed lines.
func parseJSONLEntries(content []byte, preprocess linePreprocessor) ([]parsedEntry, error) {
	reader := bufio.NewReader(bytes.NewReader(content))
	var entries []parsedEntry

	for {
		lineBytes, err := reader.ReadBytes('\n')
		if err != nil && err != io.EOF {
			return nil, fmt.Errorf("reading JSONL line: %w", err)
		}

		if len(bytes.TrimSpace(lineBytes)) > 0 {
			if e, ok := parseLine(lineBytes, preprocess); ok {
				entries = append(entries, e)
			}
		}

		if err == io.EOF {
			break
		}
	}

	return entries, nil
}

// parseLine converts a single JSONL line into a parsedEntry.
// Returns ok=false for dropped/malformed lines.
func parseLine(lineBytes []byte, preprocess linePreprocessor) (parsedEntry, bool) {
	var raw map[string]json.RawMessage
	if err := json.Unmarshal(lineBytes, &raw); err != nil {
		return parsedEntry{}, false
	}

	if preprocess != nil {
		raw = preprocess(raw)
	}

	kind := normalizeKind(raw)
	if kind == "" {
		return parsedEntry{}, false
	}

	e := parsedEntry{
		kind: kind,
		ts:   raw["timestamp"],
	}

	msg := parseMessage(raw)

	switch kind {
	case transcript.TypeAssistant:
		if msg != nil {
			e.id = unquote(msg["id"])
			if contentRaw, ok := msg["content"]; ok {
				e.content = stripAssistantContent(contentRaw)
			}
			e.inputTokens, e.outputTokens = extractUsageTokens(msg)
		}

	case transcript.TypeUser:
		e.userID = unquote(raw["promptId"])
		if msg != nil {
			if contentRaw, ok := msg["content"]; ok {
				uc := extractUserContent(contentRaw)
				e.userText = uc.text
				e.userImages = uc.images
				e.toolResults = uc.toolResults
			}
		}
		// Enrich tool results with metadata from toolUseResult.
		if turRaw, ok := raw["toolUseResult"]; ok {
			var tur map[string]json.RawMessage
			if json.Unmarshal(turRaw, &tur) == nil {
				e.toolResults = enrichToolResults(e.toolResults, tur)
			}
		}
	}

	return e, true
}

// mergeAssistantEntries combines two assistant entries with the same message ID.
// Content arrays are concatenated; the later timestamp and token counts win
// (streaming fragments report cumulative usage, so the last fragment is final).
func mergeAssistantEntries(a, b parsedEntry) parsedEntry {
	merged := a
	merged.ts = b.ts
	if b.inputTokens > 0 {
		merged.inputTokens = b.inputTokens
	}
	if b.outputTokens > 0 {
		merged.outputTokens = b.outputTokens
	}

	var aBlocks, bBlocks []json.RawMessage
	_ = json.Unmarshal(a.content, &aBlocks) //nolint:errcheck // best-effort merge
	_ = json.Unmarshal(b.content, &bBlocks) //nolint:errcheck // best-effort merge
	all := append(aBlocks, bBlocks...)      //nolint:gocritic // intentional append to new slice
	if data, err := json.Marshal(all); err == nil {
		merged.content = data
	}

	return merged
}

// inlineToolResults adds "result" fields to matching tool_use blocks in the
// assistant entry's content, using outputs from user tool_result entries.
func inlineToolResults(assistant, user parsedEntry) parsedEntry {
	var blocks []map[string]json.RawMessage
	if json.Unmarshal(assistant.content, &blocks) != nil || len(blocks) == 0 {
		return assistant
	}

	for _, tr := range user.toolResults {
		// Find the tool_use block matching this tool_use_id.
		idx := -1
		for i := len(blocks) - 1; i >= 0; i-- {
			if unquote(blocks[i]["type"]) == transcript.ContentTypeToolUse {
				if tr.toolUseID == "" || unquote(blocks[i]["id"]) == tr.toolUseID {
					idx = i
					break
				}
			}
		}
		// No matching tool_use block: do not attach a result to unrelated content.
		if idx == -1 {
			continue
		}

		blocks[idx]["result"] = buildToolResult(tr)
	}

	if data, err := json.Marshal(blocks); err == nil {
		assistant.content = data
	}

	return assistant
}

// buildToolResult constructs the compact result object for a tool_use block,
// including optional rich metadata (file, matchCount) when available.
func buildToolResult(tr toolResultEntry) json.RawMessage {
	r := toolResultJSON{
		Output:     tr.output,
		Status:     "success",
		MatchCount: tr.matchCount,
	}
	if tr.isError {
		r.Status = toolResultStatusError
	}
	if tr.file != nil {
		r.File = &toolResultFileJSON{
			FilePath: tr.file.filePath,
			NumLines: tr.file.numLines,
		}
	}
	b, err := json.Marshal(r)
	if err != nil {
		return nil
	}
	return b
}

// extractUsageTokens extracts input_tokens and output_tokens from a Claude
// message's "usage" object. Returns (0, 0) if usage is absent or malformed.
func extractUsageTokens(msg map[string]json.RawMessage) (inputTokens, outputTokens int) {
	usageRaw, ok := msg["usage"]
	if !ok {
		return 0, 0
	}
	var usage struct {
		InputTokens  int `json:"input_tokens"`
		OutputTokens int `json:"output_tokens"`
	}
	if json.Unmarshal(usageRaw, &usage) != nil {
		return 0, 0
	}
	return usage.InputTokens, usage.OutputTokens
}

// isEmptyContentArray returns true if raw is a JSON empty array (`[]`).
func isEmptyContentArray(raw json.RawMessage) bool {
	var arr []json.RawMessage
	return json.Unmarshal(raw, &arr) == nil && len(arr) == 0
}

func hasToolResults(e parsedEntry) bool {
	return len(e.toolResults) > 0
}

type toolResultEntry struct {
	toolUseID string
	output    string
	isError   bool
	// Rich metadata extracted from toolUseResult (optional).
	file       *toolResultFile // Read/Edit: file path and line count
	matchCount int             // Grep: number of matching files
}

// toolResultFile carries structured file metadata from Read/Edit tool results.
type toolResultFile struct {
	filePath string
	numLines int // 0 if not available (e.g. Edit results)
}

// enrichToolResults extracts structured metadata from a toolUseResult envelope
// and attaches it to the corresponding tool result entries.
//
// Claude Code's toolUseResult has different shapes per tool:
//   - Bash:  {stdout, stderr, interrupted, ...}
//   - Read:  {type:"text", file:{filePath, numLines, content, ...}}
//   - Grep:  {numFiles, numLines, filenames, content, mode}
//   - Edit:  {filePath, oldString, newString, structuredPatch, ...}
func enrichToolResults(results []toolResultEntry, tur map[string]json.RawMessage) []toolResultEntry {
	// Bash-style: stdout provides the output text.
	if stdout := unquote(tur["stdout"]); stdout != "" {
		switch len(results) {
		case 0:
			// Keep compatibility with transcripts that only include toolUseResult.
			results = append(results, toolResultEntry{output: stdout})
		case 1:
			results[0].output = stdout
		}
	}

	// Read-style: file object with filePath and numLines.
	if fileRaw, ok := tur["file"]; ok {
		var file struct {
			FilePath string `json:"filePath"`
			NumLines int    `json:"numLines"`
		}
		if json.Unmarshal(fileRaw, &file) == nil && file.FilePath != "" {
			applyToSingleResult(results, func(tr *toolResultEntry) {
				tr.file = &toolResultFile{filePath: file.FilePath, numLines: file.NumLines}
			})
		}
	}

	// Edit-style: top-level filePath.
	if filePath := unquote(tur["filePath"]); filePath != "" {
		applyToSingleResult(results, func(tr *toolResultEntry) {
			// Edit results don't have numLines.
			tr.file = &toolResultFile{filePath: filePath}
		})
	}

	// Grep-style: numFiles as match count.
	if numFilesRaw, ok := tur["numFiles"]; ok {
		var n int
		if json.Unmarshal(numFilesRaw, &n) == nil && n > 0 {
			applyToSingleResult(results, func(tr *toolResultEntry) {
				tr.matchCount = n
			})
		}
	}

	return results
}

// applyToSingleResult applies fn to the first (and expected only) tool result.
// toolUseResult is a single-tool envelope, so this is only meaningful when
// there's exactly one result entry.
func applyToSingleResult(results []toolResultEntry, fn func(*toolResultEntry)) {
	if len(results) == 1 {
		fn(&results[0])
	}
}

// parseMessage extracts and parses the "message" field from a JSONL transcript
// line. All JSONL agents nest content inside a "message" object.
func parseMessage(raw map[string]json.RawMessage) map[string]json.RawMessage {
	msgRaw, ok := raw["message"]
	if !ok {
		return nil
	}
	var msg map[string]json.RawMessage
	if json.Unmarshal(msgRaw, &msg) == nil {
		return msg
	}
	return nil
}

// userContent holds the extracted parts of a user message content array.
type userContent struct {
	text        string
	images      []json.RawMessage
	toolResults []toolResultEntry
}

// extractUserContent separates user message content into text, images, and tool_result entries.
// IDE context tags (e.g. <user_query>, <ide_opened_file>) are stripped from user text.
func extractUserContent(contentRaw json.RawMessage) userContent {
	var str string
	if json.Unmarshal(contentRaw, &str) == nil {
		return userContent{text: textutil.StripIDEContextTags(str)}
	}

	var blocks []json.RawMessage
	if json.Unmarshal(contentRaw, &blocks) != nil {
		return userContent{}
	}

	var uc userContent

	for _, blockRaw := range blocks {
		var block map[string]json.RawMessage
		if json.Unmarshal(blockRaw, &block) != nil {
			continue
		}
		blockType := unquote(block["type"])

		switch blockType {
		case "tool_result":
			var isErr bool
			if raw, ok := block["is_error"]; ok {
				_ = json.Unmarshal(raw, &isErr) //nolint:errcheck // best-effort
			}
			uc.toolResults = append(uc.toolResults, toolResultEntry{
				toolUseID: unquote(block["tool_use_id"]),
				output:    unquote(block["content"]),
				isError:   isErr,
			})

		case "image":
			uc.images = append(uc.images, blockRaw)

		case transcript.ContentTypeText:
			stripped := textutil.StripIDEContextTags(unquote(block[transcript.ContentTypeText]))
			if stripped != "" {
				uc.text += stripped + "\n\n"
			}
		}
	}

	uc.text = strings.TrimSpace(uc.text)
	return uc
}

func stripAssistantContent(contentRaw json.RawMessage) json.RawMessage {
	var str string
	if json.Unmarshal(contentRaw, &str) == nil {
		return contentRaw
	}

	var blocks []map[string]json.RawMessage
	if json.Unmarshal(contentRaw, &blocks) != nil {
		return contentRaw
	}

	result := make([]map[string]json.RawMessage, 0, len(blocks))
	for _, block := range blocks {
		blockType := unquote(block["type"])

		if blockType == "thinking" || blockType == "redacted_thinking" {
			continue
		}

		if blockType == transcript.ContentTypeToolUse {
			stripped := make(map[string]json.RawMessage)
			copyField(stripped, block, "type")
			copyField(stripped, block, "id")
			copyField(stripped, block, "name")
			copyField(stripped, block, "input")
			result = append(result, stripped)
			continue
		}

		result = append(result, block)
	}

	b, err := json.Marshal(result)
	if err != nil {
		return contentRaw
	}
	return b
}

// copyField copies a single key from src to dst if it exists.
func copyField(dst, src map[string]json.RawMessage, key string) {
	if v, ok := src[key]; ok {
		dst[key] = v
	}
}

// unquote JSON-decodes a raw message as a string. Returns "" on failure.
func unquote(raw json.RawMessage) string {
	var s string
	if json.Unmarshal(raw, &s) == nil {
		return s
	}
	return ""
}

